kid.example:
team.PlayerAdded:Connect(function(player)
    print(player.Name .. " has joined the team")
end)

team.PlayerRemoved:Connect(function(player)
    print(player.Name .. " has left the team")
end)

tool.Activated:Connect(function()
    print("Swing!")
end)

tool.Equipped:Connect(function(mouse)
    print("Holding the tool")
end)

tool.Unequipped:Connect(function()
    print("Tool put away")
end)

examples.code:
local tool = script.Parent

tool.Equipped:Connect(function()
    print(tool.Name .. " equipped")
end)

tool.Activated:Connect(function()
    print(tool.Name .. " used!") -- runs when the player clicks while holding it
end)

tool.Unequipped:Connect(function()
    print(tool.Name .. " put away")
end)
